"""Render age/version comparison from frozen v2 results only."""
import json
from .pipeline import ROOT
from .scenario_study import sha


def write_report(s,directory):
    sel=s['selection'];lines=['# Давность данных и смена версии GFS','',
      '13 октября 2026. Исследование станции Краснодар 34929, март–май. Сад и локация пилота не выбраны.','',
      'Проверены возрастные веса, скидка старым версиям и поправки на режим GFS. Лучший новый вариант покрывает больше холодных ночей валидации, но хуже предсказывает минимум; контроль не подтверждает устойчивого выигрыша без расширения диапазона. По 2023–2024 сохранён risk_5_lower_95. Полевая выдача остаётся GFS.','',
      '## Что реализовано','',
      'Использован тот же полный архив: 275 обучающих ночей 2021–2023, из них 30 холодных. Калибровка не пополнена старыми ошибками: финальный пул только 2024, 91 полная ночь. Все старые холодные ночи сохраняются в обучении с положительными весами; ни одна не размножается искусственно и не подменяется реанализом.',
      'Вес = 2^(-(год обучающего среза − год ночи)/период полураспада) × коэффициент режима. Проверены периоды 1 и 2 сезона, коэффициенты старых режимов 0.25/0.5 против 1 для нового, их комбинации и два варианта с индикаторами исторического режима. Веса нормализованы до среднего 1 на каждом fit, чтобы не менять масштаб регуляризации только из-за суммы весов. Веса и год среза определяются датой/выпуском и обучающими годами; факт холода не влияет на вес. При контроле 2025/2026 веса и параметры не пересчитываются.',
      'Семь политик × три головы ошибки: log-scale Ridge100, раздельные log-tails Ridge10 и квантильные деревья 100/depth2/minleaf20/lr.05. Плюс два прежних диапазона: всего 23 заранее заданных варианта. Для каждого fit используется взвешенный scaler, Huber alpha1 и взвешенное обучение ошибки на шести исключённых блоках целых ночей. Каждая точечная модель исключает цели своего блока.',
      'Базовые 13 признаков — агрегаты T/RH/точки росы/дефицита точки росы/ветра, без облачности. Политики version_offsets добавляют два индикатора исторических режимов при общих погодных зависимостях. Новый режим — опорный. Это регуляризованные эффекты режима, а не отдельная модель на 9 холодных ночах. И точечная голова, и голова ошибки меняются в эксперименте; выбранные старые модели не переписаны.','',
      '## Реестр режимов','',
      '| Режим | Выпуск с | Выпуск до |','|---|---|---|']
    for r in sel['protocol']['version_registry']:lines.append(f"| {r['name']} | {r['from']} | {r['until']} |")
    lines+=['','Границы крупных переходов: GFS v16 с выпуска 22.03.2021 12UTC и v16.3 с выпуска 29.11.2022 12UTC. Это укрупнённые режимы обновления, не полный перечень патчей и не версия, извлечённая из каждого GRIB. Реестр ограничен проверенным архивным окном до 01.06.2026; будущие версии автоматически не считаются прежними.',
      'В первом fold fit2021–22→2023 нового режима ещё нет в обучении. Исследовательские метрики сохраняют все такие ночи для диагностики переноса, но безопасная выдача отвергает unseen_gfs_regime. Финальный fit2021–23 включает новый режим; в контрольных 2025/2026 неизвестных обучению режимов не было.','',
      '## Численная ревизия до контроля','',
      'В первой реализации взвешенная дисперсия постоянного индикатора версии могла стать очень малым положительным числом из-за округления. В OOF-блоке это создавало искусственные большие остатки и диапазоны. Обнаружено на 2023–2024 до открытия нового контроля. V1 source/protocol/selection сохранены в models/research-regime-errors для аудита, контроль V1 не запускался.',
      'В V2 точно постоянный столбец определяется через размах и получает scale=1. Политики, гиперпараметры, ограничения и критерий выбора остались прежними. Отдельно сохранены regime_error_v2.py, regime_error_study_v2.py, config/regime_error_v2.json и models/research-regime-errors-v2. Добавлены проверки постоянного столбца и блока без одного режима. Для воспроизведения использовать V2; гигантская ширина V1 не является реальной погодной неопределённостью.','',
      '## Выбор только по 2023–2024','',
      'Fit2021–22→validation2023 и fit2021–23→validation2024; исходные сравнения fit2022→2023 и fit2022–23→2024. Валидационная калибровка unweighted leave-one-night-out исключает проверяемую ночь. Другие даты сезона доступны, включая поздние: это ретроспективная диагностика, не перспективная проверка всех валидационных ночей. Финальная калибровка 2024 также участвует в выборе, поэтому независимой гарантии покрытия нет.',
      'Ограничения до контроля: покрытие всех ≥ исходного симметричного; point MAE ≤ исходной Huber; ширина тёплых ≤105% симметричного; средняя ширина ≤105% сохранённого холодного диапазона. Среди допустимых: меньше холодных непокрытий, затем меньше сбалансированный interval score90 холодных/тёплых, затем ширина. Если новых допустимых нет, сохраняется прежний вариант. Лучший новый вариант при провале ограничений показан только как диагностический кандидат; парный uniform той же семьи заморожен до контроля.','',
      '| Вариант | Покрытие холодных | MAE минимума | Ширина всех | Ширина холодных | Штраф холодных | Допустим |','|---|---:|---:|---:|---:|---:|---|']
    for name,r in sel['pooled_validation'].items():
        lines.append(f"| {name} | {r['cold_covered']}/{r['cold_nights']} | {r['mae_c']:.3f} | {r['mean_width_c']:.3f} | {r['cold_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} | {'да' if all(sel['gates'][name].values()) else 'нет'} |")
    lines+=['',f"Выбран {sel['winner']}. Диагностический кандидат {sel['diagnostic']}, парное сравнение {sel['matched_uniform']}.",
      'Индикаторы версии повысили cold coverage 6/7→7/7, но расширили средний диапазон 5.065→5.322°C и ухудшили point MAE 1.319→1.386. Исходная Huber точнее:1.298, сохранённый диапазон уже покрывает7/7 и имеет меньший холодный штраф5.688 против5.963. Все новые политики не прошли ограничение point MAE; некоторые также не прошли ширину. Возрастные веса сами по себе не победили.','',
      '## Концентрация весов финального обучения','',
      '| Политика | Полных ночей | Эффективный размер по весам | Вес старого v15 | Вес раннего v16 | Вес нового режима |','|---|---:|---:|---:|---:|---:|']
    for name,a in sel['folds'][-1]['training_weight_audit'].items():
        sums=[a['regimes'].get(r['name'],{}).get('weight_sum',0) for r in sel['protocol']['version_registry']]
        n=sum(v['nights'] for v in a['regimes'].values())
        lines.append(f"| {name} | {n} | {a['effective_nights']:.1f} | {sums[0]:.1f} | {sums[1]:.1f} | {sums[2]:.1f} |")
    lines+=['','Эффективный размер = (сумма весов)^2 / сумма квадратов весов. Это мера концентрации весов, а не число независимых погодных событий. Сильное уменьшение веса старых данных уменьшает доступную информацию; редкие холодные случаи не становятся дополнительными независимыми событиями.','',
      '## Контроль после фиксации выбора','',
      '| Год | Метод | Покрытие всех | Холодных | MAE минимума | Ширина всех | Ширина холодных | Штраф холодных |','|---|---|---:|---:|---:|---:|---:|---:|']
    names={'gfs':'GFS + глобальная ошибка2024','legacy_huber':'Исходный Huber','previous_cold_range':'Сохранённый диапазон',
           'matched_uniform':'Архив2021–23 без учёта версии','weighted_candidate':'Индикаторы версии · кандидат'}
    for year,season in s['seasons'].items():
        for name,label in names.items():
            r=season['scores'][name]
            lines.append(f"| {year} | {label} | {r['covered']}/{r['nights']} | {r['cold_covered']}/{r['cold_nights']} | {r['mae_c']:.3f} | {r['mean_width_c']:.3f} | {r['cold_mean_width_c']:.3f} | {r['cold_interval_score']:.3f} |")
    lines+=['','Interval score90 = ширина +20×выход факта за границу; меньше лучше. Для GFS диапазон — отдельная калибровка ошибки2024, не собственный вероятностный прогноз.',
      'У того же квантильного алгоритма на том же архиве индикаторы версии в2025 повышают общее покрытие81/91→84/91, холодное остаётся3/6. Средняя ширина5.632→5.851°C растёт примерно на3.9%, холодный штраф20.931→16.947 снижается. В2026 общее покрытие84/86→85/86, холодное остаётся4/4; средняя ширина5.653→5.833°C растёт примерно на3.2%, холодный штраф6.610→6.866 ухудшается. Дополнительное покрытие относится к тёплым ночам.',
      'Сохранённый выбранный диапазон имеет те же cold coverage3/6 и4/4, холодный штраф15.532 и6.404 — лучше диагностического16.947 и6.866. Новый кандидат в среднем уже сохранённого примерно на4–5%, но этот выигрыш не компенсирует худшее качество холода и нарушение point MAE на валидации. Замена не произведена, по2025/2026 другую политику не выбирали.',
      'Контрольные2025/2026 ранее просмотрены в других исследованиях. Они исключены из нового обучения/подбора/калибровки, но не являются новым слепым тестом.','',
      '## Детектор и продукт','',
      '| Год | Попадания | Пропуски | Ложные тревоги | Проверено масок |','|---|---:|---:|---:|---:|']
    for year,season in s['seasons'].items():
        d=season['detector'];lines.append(f"| {year} | {d.get('hits',0)} | {d.get('misses',0)} | {d.get('false_alarms',0)} | {season['detector_masks_verified']} |")
    lines+=['','Все184 маски event_duration_weather@0.25, начало и длительность совпали с прежними snapshots. Оригинальные точки и диапазоны сохранённого варианта неизменны; исследовательские кандидаты имеют собственную точечную голову. Неполные факты7 контрольных ночей не заполняются. Все трудные/OOD случаи сохраняются в сравнении, но безопасная скорректированная выдача их отвергает.',
      'safe_prediction V2 также отвергает другой сайт, плохие признаки, другой выпуск/горизонт/сезон, дату вне реестра и режим, которого нет в обучении любой головы. Номинальные90% не обещают покрытия именно холодных ночей или вероятности повреждения яблони. Полевой GFS, паспорт без локации, журнал решений и набор пользовательского тестирования не менялись; серверы и вкладки с черновиками не перезапускались.','',
      '## Вывод','',
      'Реализован воспроизводимый механизм давности и смены режима, а также исправлена численная проблема взвешенного scaler. Но на малом числе холодных валидационных событий он не доказал выигрыша без расширения и ухудшения других показателей. Дальнейший подбор тех же контрольных лет не даст независимого доказательства. Следующий источник улучшения — новые совместимые холодные события/перспективная проверка и наблюдения выбранного сада.','',
      '## Воспроизведение','',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.regime_error_study_v2 --select-only',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.regime_error_study_v2',
      '    .\\.venv\\Scripts\\python.exe -X utf8 -m agro_checker.regime_error_report','',
      'Используются уже сохранённые локальные архивы. Повторная селекция проверяет источники, конфигурацию, родительские модели, данные и артефакты поSHA и возвращает сохранённый выбор. V1 не использовать для контроля или выдачи. Новый эксперимент должен иметь новый каталог и протокол; замороженные learner/selector не редактировать.',
      'Выбор зафиксирован: '+sel['selection_saved_at_utc']+'.','SHA выбора V2: '+s['selection_sha256']+'.','SHA прогнозных кадров: '+s['forecast_sha256']+'.','',
      '[Численная сводкаV2](REGIME_ERROR_V2_SUMMARY.json). [График](assets/regime-error-quality.png). [Предыдущий архивный эксперимент](EXTENDED_ERROR_REPORT.md).','',
      'Первичные источники границ: [NOAA/EMC GFSv16](https://www.emc.ncep.noaa.gov/emc/pages/numerical_forecast_systems/gfs/implementations.php), [NWS SCN22-104: GFSv16.3.0](https://www.weather.gov/media/notification/pdf2/scn22-104_gfs.v16.3.0_aaa.pdf). Реестр укрупняет версии и не доказывает одинаковую статистику ошибок внутри каждого режима.']
    (directory/'REGIME_ERROR_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')


def figure(s,directory):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    names=['previous_cold_range','matched_uniform','weighted_candidate'];labels=['Сохранённый','Тот же архив\nбез учёта версии','Учёт версии\nкандидат'];colors=['#36704e','#7390a2','#9261a5']
    fig,axes=plt.subplots(1,3,figsize=(13.8,4.7));fig.patch.set_facecolor('#f2f5ef')
    for ax,(title,key) in zip(axes,[('Покрытие всех ночей','coverage'),('Средняя ширина, °C','mean_width_c'),('Штраф холодных ночей ↓','cold_interval_score')]):
        for j,name in enumerate(names):
            rows=[s['seasons'][y]['scores'][name] for y in ['2025','2026']];values=[r[key] for r in rows];positions=[k+(j-1)*.24 for k in [0,1]]
            ax.bar(positions,values,.24,color=colors[j],label=labels[j])
            for x,v,r in zip(positions,values,rows):
                label=f"{r['covered']}/{r['nights']}" if key=='coverage' else f'{v:.2f}'
                ax.text(x,v+.015 if key=='coverage' else v*1.015,label,ha='center',fontsize=9)
        ax.set_xticks([0,1],['2025','2026']);ax.set_title(title,fontsize=12);ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.15);ax.set_axisbelow(True)
        if key=='coverage':ax.set_ylim(0,1.15);ax.set_yticks([0,.25,.5,.75,1],['0%','25%','50%','75%','100%'])
        else:ax.set_ylim(0,ax.get_ylim()[1]*1.1)
    handles,legend=axes[0].get_legend_handles_labels();fig.legend(handles,legend,loc='lower center',ncol=3,frameon=False,bbox_to_anchor=(.5,.07))
    fig.suptitle('Учёт версии GFS: улучшение 2025 не повторилось в 2026',fontsize=15,y=.98)
    fig.text(.5,.02,'Холодное покрытие у всех показанных: 3/6 и 4/4. Выбор только по 2023–2024. Прежний вариант сохранён.',ha='center',fontsize=10)
    fig.tight_layout(rect=[0,.21,1,.93]);directory.mkdir(parents=True,exist_ok=True);fig.savefig(directory/'regime-error-quality.png',dpi=150);plt.close(fig)


